/// <summary>
/// MPJ_15231_Customer Statement DCP 07/02/2022
/// Class <c>METPrintMgmtReportFormatPopulatorAppSuite_Extension</c> populates the PrintMgmtReportFormat table used for print management
/// with the documents.
/// </summary>
[ExtensionOf(classStr(PrintMgmtReportFormatPopulator))]
public final class KPMGPrintMgmtReportFormatPopulatorAppSuite_Extension
{
    #ISOCountryRegionCodes
    #PrintMgmtSetup

}

Method.Source:
    /// <summary>
    /// Add Report to Print Management configuration
    /// </summary>
    protected void addDocuments()
    {
        this.addOther(  PrintMgmtDocumentType::KPMGMultiCustAccountStatement,
                        ssrsReportStr(KPMGCustAccountStatementExt, ReportMultiCust),
                        ssrsReportStr(KPMGCustAccountStatementExt, ReportMultiCust),
                        #NoCountryRegionId);
        //MPJ_31513 Invoicing Design
        
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(KPMGSalesInvoice, MFG), ssrsReportStr(KPMGSalesInvoice, MFG), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(KPMGSalesInvoice, CCC), ssrsReportStr(KPMGSalesInvoice, CCC), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(KPMGSalesInvoice, CSD), ssrsReportStr(KPMGSalesInvoice, CSD), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(KPMGSalesInvoice, ALM), ssrsReportStr(KPMGSalesInvoice, ALM), #NoCountryRegionId);
        this.addOther(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(KPMGSalesInvoice, IHG), ssrsReportStr(KPMGSalesInvoice, IHG), #NoCountryRegionId);

        next addDocuments();
    }
